<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ArrowRightLeft, Plus, RotateCcw } from 'lucide-vue-next'
import SectionPanel from '../components/SectionPanel.vue'
import StatusBadge from '../components/StatusBadge.vue'
import { accountingApi, type AccountRecord, type ExpenseRecord, type FinancialAccountRecord, type TransferRecord } from '../api/accounting'
import type { CurrencyUnit } from '../utils/currency'
import { formatMoney, parseMoneyInput } from '../utils/currency'
import { currentCanonicalDate, formatDateTime } from '../utils/date'
import { normalizeError } from '../ui/feedback'
import SelectField from '../components/SelectField.vue'

const props=defineProps<{tab:string;currencyUnit:CurrencyUnit;accounts:AccountRecord[];financial:FinancialAccountRecord[];suppliers:any[]}>();const emit=defineEmits<{notify:[string]}>();const expenses=ref<ExpenseRecord[]>([]);const transfers=ref<TransferRecord[]>([]);const error=ref('');const expense=ref({categoryAccountId:'ACC-EXP-OTHER',financialAccountId:'FIN-CASH',description:'',payee:'',supplierId:'',amount:'',paymentMethod:'cash'});const transfer=ref({sourceFinancialAccountId:'FIN-CASH',destinationFinancialAccountId:'FIN-BANK',amount:'',reference:'',transferDate:currentCanonicalDate()})
async function load(){try{[expenses.value,transfers.value]=await Promise.all([accountingApi.expenses(),accountingApi.transfers()])}catch(e){error.value=normalizeError(e).message}}onMounted(load)
async function createExpense(){try{const amount=parseMoneyInput(expense.value.amount,props.currencyUnit);if(!amount||amount<=0)throw new Error('Enter a positive amount');const v=await accountingApi.createExpense({...expense.value,amountRial:amount});expenses.value=[v,...expenses.value];expense.value={...expense.value,description:'',payee:'',amount:''};emit('notify','Expense posted.')}catch(e){error.value=normalizeError(e).message}}
async function createTransfer(){try{const amount=parseMoneyInput(transfer.value.amount,props.currencyUnit);if(!amount||amount<=0)throw new Error('Enter a positive amount');const v=await accountingApi.createTransfer({...transfer.value,amountRial:amount});transfers.value=[v,...transfers.value];transfer.value={...transfer.value,amount:'',reference:''};emit('notify','Transfer posted.')}catch(e){error.value=normalizeError(e).message}}
async function reverseExpense(v:ExpenseRecord){try{const next=await accountingApi.reverseExpense(v.id);expenses.value=expenses.value.map(x=>x.id===next.id?next:x);emit('notify','Expense reversed.')}catch(e){error.value=normalizeError(e).message}}
async function reverseTransfer(v:TransferRecord){try{const next=await accountingApi.reverseTransfer(v.id);transfers.value=transfers.value.map(x=>x.id===next.id?next:x);emit('notify','Transfer reversed.')}catch(e){error.value=normalizeError(e).message}}
</script>
<template><div><div v-if="error">{{error}}</div><template v-if="props.tab==='Expenses'"><SectionPanel title="Expenses" subtitle="Each expense posts a balanced debit to its category and a credit to Cash/Bank."><form @submit.prevent="createExpense"><SelectField v-model="expense.categoryAccountId" label="Category" :options="props.accounts.filter((account) => account.type === 'expense' && account.code !== '5000').map((account) => ({ label: `${account.code} · ${account.name}`, value: account.id }))" /><SelectField v-model="expense.financialAccountId" label="Financial account" :options="props.financial.map((account) => ({ label: account.name, value: account.id }))" /><input class="input input-bordered w-full min-w-0" v-model="expense.description" required placeholder="Description"/><input class="input input-bordered w-full min-w-0" v-model="expense.payee" placeholder="Payee"/><SelectField v-model="expense.supplierId" label="Supplier" :options="[{ label: 'No supplier', value: '' }, ...props.suppliers.map((supplier) => ({ label: supplier.name, value: supplier.id }))]" /><input class="input input-bordered w-full min-w-0" v-model="expense.amount" required inputmode="numeric" :placeholder="`Amount (${props.currencyUnit})`"/><button class="btn btn-ghost" type="submit"><Plus :size="15"/> Post expense</button></form></SectionPanel><SectionPanel title="Expense history" subtitle="Posted expenses are reversed, never deleted."><div v-for="v in expenses" :key="v.id"><span><strong>{{v.expenseNumber}} · {{v.description}}</strong><small>{{formatDateTime(v.expenseDate)}} · {{formatMoney(v.amountRial,props.currencyUnit)}}</small></span><span><StatusBadge :label="v.status" :tone="v.status==='Posted'?'green':'slate'"/><button class="btn btn-ghost" v-if="v.status==='Posted'" @click="reverseExpense(v)"><RotateCcw :size="14"/> Reverse</button></span></div></SectionPanel></template><template v-else><SectionPanel title="Transfers / treasury" subtitle="Move value between Cash and Bank without income or expense effect."><form @submit.prevent="createTransfer"><SelectField v-model="transfer.sourceFinancialAccountId" label="From account" :options="props.financial.map((account) => ({ label: `From ${account.name}`, value: account.id }))" /><SelectField v-model="transfer.destinationFinancialAccountId" label="To account" :options="props.financial.map((account) => ({ label: `To ${account.name}`, value: account.id }))" /><input class="input input-bordered w-full min-w-0" v-model="transfer.amount" required inputmode="numeric" :placeholder="`Amount (${props.currencyUnit})`"/><input class="input input-bordered w-full min-w-0" v-model="transfer.reference" placeholder="Reference"/><button class="btn btn-ghost" type="submit"><ArrowRightLeft :size="15"/> Post transfer</button></form></SectionPanel><SectionPanel title="Transfer history" subtitle="Source is credited and destination is debited."><div v-for="v in transfers" :key="v.id"><span><strong>{{v.transferNumber}} · {{v.reference||'Transfer'}}</strong><small>{{formatDateTime(v.transferDate)}} · {{formatMoney(v.amountRial,props.currencyUnit)}}</small></span><span><StatusBadge :label="v.status" :tone="v.status==='Posted'?'green':'slate'"/><button class="btn btn-ghost" v-if="v.status==='Posted'" @click="reverseTransfer(v)"><RotateCcw :size="14"/> Reverse</button></span></div></SectionPanel></template></div></template>
